var PHASES = {1:'请求头',2:'请求体',3:'响应头',4:'响应体',5:'日志/审计'};
var VALID_ACTIONS = {block:1,deny:1,allow:1,pass:1,log:1,redirect:1,'pass,log':1,'deny,log':1,'allow,log':1};
var DEFAULT_VARS = ['REQUEST_URI','REQUEST_HEADERS:User-Agent','REQUEST_BODY','ARGS','ARGS_GET','ARGS_POST','REQUEST_HEADERS:Host','REMOTE_ADDR','REQUEST_LINE','REQUEST_METHOD'];

function sanitizeRuleId(id){
  var n=parseInt(String(id==null?'':id).replace(/\D/g,''),10);
  if(!isFinite(n)||n<1||n>999999) return null;
  return n;
}
function escapeQuotes(s){ return String(s==null?'':s).replace(/\\/g,'\\\\').replace(/"/g,'\\"'); }

function buildSecRule(spec){
  spec=spec||{};
  var id=sanitizeRuleId(spec.id);
  if(!id) return { error:'rule id 必须是 1–999999 的整数', value:'' };
  var variable=String(spec.variable||'').trim();
  if(!variable) return { error:'缺少匹配变量 variable', value:'' };
  var operator=String(spec.operator||'').trim();
  if(!operator) return { error:'缺少操作符 operator（如 @rx 或 @pm）', value:'' };
  var phase=parseInt(spec.phase,10);
  if(!(phase>=1&&phase<=5)) return { error:'phase 必须是 1–5', value:'' };
  var action=String(spec.action||'block').toLowerCase();
  var actionStr = action==='block'||action==='deny' ? 'deny,status:403' :
                  action==='allow' ? 'allow' : action==='log' ? 'pass,log' :
                  action==='pass' ? 'pass' : action;
  var parts=[];
  parts.push('id:'+id);
  parts.push('phase:'+phase);
  if(spec.msg) parts.push("msg:'"+escapeQuotes(spec.msg)+"'");
  (spec.transforms||[]).forEach(function(t){ if(t) parts.push('t:'+t); });
  parts.push(actionStr);
  if(spec.log==='no'||spec.log===false) parts.push('nolog');
  else parts.push('log');
  if(spec.severity) parts.push('severity:'+spec.severity);
  if(spec.chain) parts.push('chain');
  if(spec.tag) parts.push("tag:'"+escapeQuotes(spec.tag)+"'");
  return { error:null,
    value:'SecRule '+variable+' "'+operator.replace(/^@?/, '@')+'" "'+parts.join(',')+'"' };
}

function buildPolicy(spec){
  spec=spec||{};
  var r=buildSecRule(spec);
  if(r.error) return { error:r.error, value:null };
  return { error:null, value: {
    name: spec.name || ('rule-'+spec.id),
    engine: 'modsecurity-v3',
    rule: {
      id: sanitizeRuleId(spec.id),
      phase: parseInt(spec.phase,10),
      variable: String(spec.variable||'').trim(),
      operator: spec.operator,
      transforms: spec.transforms||[],
      action: String(spec.action||'block').toLowerCase(),
      msg: spec.msg||'',
      severity: spec.severity||'',
      tag: spec.tag||''
    }
  } };
}

function lintRule(spec){
  spec=spec||{};
  var issues=[];
  if(!sanitizeRuleId(spec.id)) issues.push({level:'bad',msg:'rule id 必须是 1–999999 的整数'});
  if(!String(spec.variable||'').trim()) issues.push({level:'bad',msg:'缺少匹配变量 variable'});
  if(!String(spec.operator||'').trim()) issues.push({level:'bad',msg:'缺少操作符 operator'});
  var ph=parseInt(spec.phase,10);
  if(!(ph>=1&&ph<=5)) issues.push({level:'bad',msg:'phase 必须是 1–5'});
  var act=String(spec.action||'').toLowerCase();
  if(act && !VALID_ACTIONS[act] && !VALID_ACTIONS[act+',log']) issues.push({level:'warn',msg:'动作 "'+act+'" 不在常见集合（block/allow/log/pass）'});
  if(spec.transforms && spec.transforms.some(function(t){ return !/^(lowercase|uppercase|urlDecode|urlDecodeUni|htmlEntityDecode|compressWhitespace|removeWhitespace|normalisePath|base64Decode|cmdLine|none)$/.test(t); }))
    issues.push({level:'warn',msg:'存在不常见的 transform（t:）'});
  var score=100; issues.forEach(function(i){ score-=(i.level==='bad'?25:10); });
  return { issues:issues, score:Math.max(0,score) };
}

function templates(){
  return [
    {id:'100001',name:'SQL 注入 (CRS)', variable:'ARGS|REQUEST_HEADERS', operator:'detectSQLi', phase:2, action:'block', transforms:['lowercase'], msg:'SQLi', tag:'OWASP_CRS/WEB_ATTACK/SQL_INJECTION', severity:'CRITICAL'},
    {id:'100002',name:'XSS (CRS)', variable:'ARGS|REQUEST_HEADERS', operator:'detectXSS', phase:2, action:'block', transforms:['lowercase'], msg:'XSS', tag:'OWASP_CRS/WEB_ATTACK/XSS', severity:'CRITICAL'},
    {id:'100003',name:'路径遍历', variable:'REQUEST_URI', operator:'../', phase:1, action:'block', transforms:['urlDecodeUni','lowercase'], msg:'path traversal', tag:'attack/traversal', severity:'CRITICAL'},
    {id:'100004',name:'IP 封禁', variable:'REMOTE_ADDR', operator:'@ipMatch 1.2.3.4', phase:1, action:'deny', msg:'blocked IP', severity:'ALERT'},
    {id:'100005',name:'限流 10r/s', variable:'IP', operator:'@rlimit 10', phase:1, action:'block', msg:'rate limit', severity:'WARNING'},
    {id:'100006',name:'恶意爬虫', variable:'REQUEST_HEADERS:User-Agent', operator:'@pm badbot scraper', phase:1, action:'block', transforms:['lowercase'], msg:'bad bot', tag:'bot', severity:'WARNING'},
    {id:'100007',name:'缺少 UA', variable:'&REQUEST_HEADERS:User-Agent', operator:'@eq 0', phase:1, action:'block', msg:'empty UA', severity:'WARNING'}
  ];
}

var WAFForgePure = {
  sanitizeRuleId: sanitizeRuleId, buildSecRule: buildSecRule, buildPolicy: buildPolicy,
  lintRule: lintRule, templates: templates, PHASES: PHASES, VALID_ACTIONS: VALID_ACTIONS,
  DEFAULT_VARS: DEFAULT_VARS
};
if (typeof module !== 'undefined' && module.exports) module.exports = WAFForgePure;
if (typeof window !== 'undefined') window.WAFForgePure = WAFForgePure;
